suppressPackageStartupMessages(library(tidyverse))
a <- read_csv('./output/research_extensions/28_paper_state_guarded_refresh/all_att.csv',show_col_types=FALSE)
out <- 'output/research_extensions/28_paper_state_guarded_refresh/paper_preview'; dir.create(out, recursive=TRUE, showWarnings=FALSE)
th <- theme_bw(base_size=13)+theme(panel.grid.minor=element_blank(),panel.grid.major.y=element_blank(),strip.background=element_rect(fill='#f0f0f0',colour='#888888'),panel.spacing.x=grid::unit(.8,'cm'),plot.margin=margin(10,20,10,10))
d <- a %>% filter(specification=='matched_pair_year',group=='pooled',analysis %in% c('main/log_rac_low','main/log_wac_low')) %>% mutate(side=if_else(str_detect(outcome,'rac'),'Resident-held jobs (log)','Workplace jobs (log)'),tier=factor(str_extract(outcome,'(low|mid|high)$'),levels=c('low','mid','high'),labels=c('Low wage','Middle wage','High wage')))
stopifnot(nrow(d)==6)
p <- ggplot(d,aes(tier,estimate))+geom_hline(yintercept=0,colour='grey55',linewidth=.4)+geom_errorbar(aes(ymin=estimate-1.96*std_error,ymax=estimate+1.96*std_error),width=.08,colour='#214F80',alpha=.65,linewidth=.45)+geom_point(size=2.8,colour='#214F80')+facet_wrap(~side,nrow=1)+th+theme(panel.grid.major.x=element_blank(),panel.grid.major.y=element_line(colour='#eeeeee'))+labs(y='Effect on log jobs',x=NULL)
ggsave(file.path(out,'pooled_wage.png'),p,width=10,height=4,dpi=200)
ggsave(file.path(out,'pooled_wage.pdf'),p,width=10,height=4)
write_csv(d,file.path(out,'pooled_wage_estimates.csv'))
keys <- c('s000','sa01','sa02','sa03','se01','se02','se03','si01','si02','si03')
labels <- c('All workers','29 or younger','30–54','55 or older','Low wage','Middle wage','High wage','Goods producing','Trade, transportation,\nand utilities','Other services')
d <- a %>% filter(specification=='matched_pair_year',group=='pooled',str_starts(analysis,'commute/')) %>% mutate(key=sub('avg_road_dist_from_','',outcome)) %>% filter(key %in% keys) %>% mutate(category=factor(c('All workers',rep('Age',3),rep('Monthly earnings',3),rep('Industry',3))[match(key,keys)],levels=c('All workers','Age','Monthly earnings','Industry')),label=factor(labels[match(key,keys)],levels=labels))
stopifnot(nrow(d)==10)
d$label <- factor(d$label,levels=labels,labels=c('All workers','Age ≤29','Age 30–54','Age ≥55','Low wage','Middle wage','High wage','Goods\nproducing','Trade, transport,\nand utilities','Other\nservices'))
d <- d %>% filter(key!='s000')
p <- ggplot(d,aes(label,estimate))+geom_hline(yintercept=0,colour='grey55',linewidth=.4)+geom_errorbar(aes(ymin=estimate-1.96*std_error,ymax=estimate+1.96*std_error),width=.08,colour='#829BB2',linewidth=.45)+geom_point(size=2.9,colour='#214F80')+facet_wrap(~category,nrow=1,scales='free_x')+th+theme(panel.grid.major.x=element_blank(),panel.grid.major.y=element_line(colour='#eeeeee'),panel.spacing.y=grid::unit(.6,'cm'),axis.text.x=element_text(size=11))+labs(y='Effect on commuting distance (km)',x=NULL)
ggsave(file.path(out,'commuting_subgroups.png'),p,width=13,height=4,dpi=200)
ggsave(file.path(out,'commuting_subgroups.pdf'),p,width=13,height=4)
write_csv(d,file.path(out,'commuting_subgroups_estimates.csv'))
print(d %>% select(key,observations))
